     "appro": "Il filo conduttore è il principio di effettività: la sicurezza si giudica su ciò che accade davvero nel reparto, non su ciò che è scritto nei documenti. Le procedure non applicate, i dispositivi esclusi e le prassi elusive tollerate dimostrano un difetto di organizzazione e di vigilanza.",
     "rif": "Artt. 18-20 D.lgs. 81/2008 · Cass. pen., Sez. IV, nn. 10460/2025, 22843/2025, 32520/2025",
     "nar": "Tre sentenze recenti della Corte di cassazione illustrano la ripartizione delle responsabilità. In primo luogo, l’imprudenza del lavoratore esclude la responsabilità del datore di lavoro solo se genera un rischio del tutto estraneo al lavoro affidato. In secondo luogo, l’affiancamento a un collega esperto non sostituisce la formazione. In terzo luogo, il preposto risponde anche delle attività svolte sotto la sua vigilanza, ancorché non da lui disposte. Ne discende che il rispetto delle procedure e la segnalazione delle anomalie costituiscono, per ciascun lavoratore, un obbligo e una tutela.",
