     "rif": "OMS, ICD-11, codice QD85 · D.lgs. 81/2008, art. 28 · UNI ISO 45003",
     "nar": "Il termine burnout è usato spesso in modo generico. L’Organizzazione mondiale della sanità, nell’undicesima revisione della classificazione internazionale delle malattie, in vigore dal duemilaventidue, lo descrive con il codice QD ottantacinque, nel capitolo dei fattori che influenzano lo stato di salute, e non come una condizione medica. Il burnout è definito come una sindrome derivante da uno stress cronico sul posto di lavoro che non è stato gestito con successo. Si caratterizza per tre dimensioni: una sensazione di esaurimento delle energie, una maggiore distanza mentale dal proprio lavoro, con sentimenti di negativismo o cinismo, e una ridotta efficacia professionale. L’Organizzazione precisa che il termine si riferisce specificamente ai fenomeni nel contesto lavorativo e non dovrebbe essere usato per descrivere esperienze in altri ambiti della vita. Per la prevenzione questa impostazione è importante: le cause vanno cercate nell’organizzazione del lavoro, come carichi eccessivi, scarsa autonomia, mancanza di riconoscimento, iniquità, conflitti di valori e scarso supporto. La valutazione dello stress lavoro correlato, prevista dall’articolo ventotto, è lo strumento per individuare questi fattori e intervenire prima che producano danni. La linea guida ISO quarantacinquemilatré offre un quadro per la gestione dei rischi psicosociali nel sistema di gestione.",
