     "nar": "La violenza contro gli operatori sanitari e sociosanitari è un fenomeno in crescita, che riguarda soprattutto pronto soccorso, servizi psichiatrici, guardie mediche e servizi territoriali. La legge centotredici del duemilaventi ha introdotto specifiche aggravanti per le lesioni personali commesse ai danni del personale sanitario e sociosanitario nell’esercizio delle funzioni, ha previsto la procedibilità d’ufficio e sanzioni per gli atti di violenza e minaccia, e ha istituito l’Osservatorio nazionale sulla sicurezza degli esercenti le professioni sanitarie, che monitora gli episodi e promuove la prevenzione. Il decreto legge centotrentasette del duemilaventiquattro ha rafforzato la risposta penale, prevedendo l’arresto in flagranza, anche differita sulla base di documentazione video o fotografica, e pene più severe per il danneggiamento di beni destinati all’assistenza sanitaria. Le norme penali non sostituiscono però la prevenzione, che resta un obbligo del datore di lavoro: valutazione specifica del rischio di aggressione, organizzazione degli spazi e delle vie di fuga, gestione dei tempi di attesa e della comunicazione con gli utenti, sistemi di allarme e vigilanza, formazione alla gestione dei conflitti e alla de-escalation, procedure di segnalazione e supporto psicologico alle vittime.",
     "est": true,
     "ancora": "Aggressioni al personale: il caso della sanità e dei servizi al pubblico"
