     "nar": "L’alcol e le sostanze psicoattive riducono attenzione, tempi di reazione e capacità di valutazione del rischio. La legge centoventicinque del duemilauno, all’articolo quindici, vieta l’assunzione e la somministrazione di bevande alcoliche e superalcoliche nelle attività lavorative che comportano un elevato rischio di infortuni o per la sicurezza, l’incolumità o la salute di terzi. Queste attività sono elencate nell’Intesa Stato Regioni del sedici marzo duemilasei e comprendono, tra le altre, la conduzione di veicoli e di carrelli, i lavori in quota, le mansioni sanitarie, l’insegnamento e le attività con impiego di gas tossici o esplosivi. Per verificare il rispetto del divieto possono essere effettuati controlli alcolimetrici dal medico competente o dai medici dei servizi pubblici di prevenzione. Per le sostanze stupefacenti l’Intesa del trenta ottobre duemilasette individua le mansioni a rischio per le quali il medico competente esegue gli accertamenti di assenza di tossicodipendenza. L’articolo quarantuno del testo unico prevede che le visite mediche, nei casi previsti, siano finalizzate anche a verificare l’assenza di condizioni di alcol dipendenza e di assunzione di sostanze. Accanto ai controlli servono una politica aziendale chiara, informazione e la possibilità di accedere a percorsi di supporto.",
