     "rif": "L. 22 maggio 2017, n. 81, artt. 18-23 · Protocollo nazionale sul lavoro agile, 7 dicembre 2021",
     "nar": "Il lavoro agile, disciplinato dalla legge ottantuno del duemiladiciassette, è una modalità di esecuzione del lavoro subordinato senza precisi vincoli di orario o di luogo, con prestazione svolta in parte all’interno e in parte all’esterno dei locali aziendali. È diverso dal telelavoro, in cui la postazione esterna è fissa e allestita dal datore di lavoro. L’articolo ventidue stabilisce che il datore di lavoro garantisce la salute e la sicurezza del lavoratore agile e consegna, con cadenza almeno annuale, un’informativa scritta che individua i rischi generali e i rischi specifici connessi alla particolare modalità di esecuzione del rapporto. Il lavoratore è tenuto a cooperare all’attuazione delle misure di prevenzione predisposte, ad esempio scegliendo luoghi idonei e usando correttamente i dispositivi. L’articolo ventitré estende la tutela assicurativa agli infortuni e alle malattie professionali connessi alla prestazione resa all’esterno, compresi quelli occorsi nel percorso tra l’abitazione e il luogo prescelto, quando la scelta risponde a criteri di ragionevolezza. L’accordo individuale disciplina i tempi di riposo e le misure tecniche e organizzative per assicurare la disconnessione. Il protocollo nazionale del duemilaventuno indica come buona prassi una formazione specifica sull’ergonomia della postazione, sui rischi elettrici domestici e sull’organizzazione del tempo.",
