     "nar": "L'emendamento del duemilaventiquattro alla ISO quarantacinquemilauno ha introdotto il cambiamento climatico tra le questioni di contesto; l'articolo trenta richiama espressamente la norma. I modelli possono essere asseverati dagli organismi paritetici e integrati con gli altri sistemi.",
