     "appro": "Il modello non è un documento ma un sistema in funzione: l’efficace attuazione si dimostra con registrazioni, audit, riesami e provvedimenti disciplinari applicati. La presunzione di conformità riguarda l’idoneità del modello, non la sua efficace attuazione, che va dimostrata in concreto: la certificazione UNI EN ISO 45001 non coincide con l’esimente della 231, ma ne costituisce una base solida se integrata con i requisiti dell’art. 30 e con il sistema disciplinare.",
     "rif": "Art. 30, cc. 1-5-bis e art. 51, c. 3-bis D.lgs. 81/2008 · D.M. 13 febbraio 2014 · UNI EN ISO 45001:2023",
     "nar": "Per le piccole e medie imprese il decreto del 13 febbraio 2014 ha previsto procedure semplificate per l'adozione del modello organizzativo. I modelli definiti secondo le linee guida UNI-INAIL o secondo la norma UNI EN ISO 45001 si presumono conformi per le parti corrispondenti: il decreto-legge 159 del 2025 ha sostituito con tale norma il precedente riferimento allo standard britannico OHSAS 18001. Gli organismi paritetici possono asseverare l’adozione e l’efficace attuazione del modello. Si sottolinea che il modello è un sistema in funzione, non un documento.",
