     "rif": "Art. 26, cc. 1-8 D.lgs. 81/2008",
     "nar": "Si propone un esempio di DUVRI. Un’impresa esterna deve eseguire la manutenzione dell’impianto di aspirazione di un reparto di verniciatura, con lavori in quota e a caldo. Le interferenze sono costituite dai carrelli in transito, dai solventi infiammabili e dai lavori sovrastanti postazioni presidiate. Le misure consistono nell’esecuzione a reparto fermo, nella bonifica, nel permesso di lavoro a caldo, nella delimitazione delle aree e in una riunione di coordinamento verbalizzata. I costi della sicurezza da interferenze sono indicati nel contratto e non sono soggetti a ribasso.",
