     "nar": "Le cadute dall’alto sono tra le prime cause di infortunio mortale. Il testo unico, all’articolo centoundici, impone di privilegiare le misure di protezione collettiva, come parapetti, reti e impalcati, rispetto a quelle individuali. Quando la protezione collettiva non è realizzabile, l’articolo centoquindici prevede l’uso di sistemi di protezione individuale contro le cadute, composti da imbracatura per il corpo, cordino con assorbitore di energia o dispositivo retrattile, connettori e un punto o una linea di ancoraggio idonei. I dispositivi di ancoraggio sono classificati dalla norma UNI EN settecentonovantacinque e le linee di ancoraggio permanenti vanno progettate e installate secondo le istruzioni. Un aspetto spesso trascurato è il tirante d’aria, cioè lo spazio libero necessario sotto il punto di ancoraggio perché il sistema arresti la caduta senza che il lavoratore urti il suolo o un ostacolo: considera la lunghezza del cordino, l’allungamento dell’assorbitore, l’altezza del lavoratore e un margine di sicurezza. Infine serve sempre un piano di soccorso: un lavoratore rimasto sospeso nell’imbracatura deve essere recuperato rapidamente, perché la sospensione inerte prolungata può causare gravi disturbi circolatori. I sistemi di arresto caduta sono dispositivi di terza categoria e il loro uso richiede addestramento.",
