     "rif": "D.lgs. 81/2008, artt. 28 c. 1 e 37 c. 13 · Accordo Stato-Regioni 17 aprile 2025",
     "nar": "In molte aziende lavorano persone di madrelingua diversa dall’italiano, e la formazione deve tenerne conto. L’articolo trentasette, comma tredici, stabilisce che il contenuto della formazione deve essere facilmente comprensibile per i lavoratori e consentire loro di acquisire le conoscenze e competenze necessarie; per i lavoratori immigrati la formazione avviene previa verifica della comprensione e conoscenza della lingua veicolare utilizzata. L’articolo ventotto, inoltre, include la provenienza da altri Paesi tra i fattori da considerare nella valutazione dei rischi. Nella pratica questo comporta di verificare all’inizio il livello di comprensione dell’italiano, e di scegliere di conseguenza gli strumenti: mediatori culturali o docenti che conoscono la lingua dei partecipanti, materiali bilingue, uso intensivo di pittogrammi, fotografie del reparto e dimostrazioni pratiche. La verifica dell’apprendimento dovrebbe privilegiare prove pratiche e osservazione dei comportamenti, più che test scritti. Le istruzioni essenziali e la segnaletica di reparto possono essere tradotte nelle lingue presenti. Un attestato rilasciato a chi non ha compreso il corso non dimostra l’adempimento: in caso di infortunio la giurisprudenza valuta l’effettiva comprensione delle informazioni ricevute.",
     "est": true,
