     "lead": "Le persone non valutano i rischi solo in base a probabilità e gravità: la percezione dipende da fattori psicologici e sociali che il comunicatore deve conoscere.",
     "punti": [
      "Rischi percepiti come più gravi: involontari, incontrollabili, catastrofici, poco conosciuti, che colpiscono persone note (studi di Slovic)",
      "Rischi sottovalutati: abituali, volontari, con effetti differiti (rumore, MMC, agenti chimici cronici)",
      "Bias di ottimismo («a me non succede») ed effetto della familiarità con il compito",
      "Normalizzazione della devianza: lo scostamento dalla regola che non produce danni diventa la nuova norma",
      "Conseguenza: comunicare i rischi cronici con esempi concreti, storie, dati locali e rendere visibili le conseguenze differite"
     ],
     "appro": "La normalizzazione della devianza è stata descritta da Diane Vaughan nell’analisi del disastro del Challenger e si ritrova in molti infortuni sul lavoro: prassi scorrette tollerate a lungo diventano «il modo in cui si lavora». Il RSPP la contrasta con osservazioni sul campo, analisi dei quasi incidenti e coinvolgimento dei preposti.",
     "rif": "UNI EN ISO 45001:2023, punto 7.4",
     "nar": "Le persone non percepiscono i rischi in modo razionale. Sono temuti di più i rischi involontari, catastrofici e poco conosciuti; sono sottovalutati quelli abituali e con effetti differiti, come il rumore o la movimentazione dei carichi. C’è poi la normalizzazione della devianza: una scorciatoia che non provoca danni diventa la regola. Per i rischi cronici servono esempi concreti, storie e dati che rendano visibili le conseguenze.",
